DECLARE
    V_CANTIDAD  NUMBER;
    V_COSTO     NUMBER(12,2);
    V_BODEGUERO NUMBER;
BEGIN
    DBMS_RANDOM.SEED(9255);
    FOR S IN 1..12 LOOP
        V_BODEGUERO := 4 + (S - 1) * 7 + 4;
        FOR P IN 1..42 LOOP
            SELECT EXISTENCIA_MINIMA * 4 + 25 + TRUNC(DBMS_RANDOM.VALUE(0, 40)), PRECIO_COSTO
              INTO V_CANTIDAD, V_COSTO
              FROM PRODUCTO_9255
             WHERE ID_PRODUCTO = P;
            PRC_REGISTRA_MOV_INVENTARIO_9255('INVENTARIO_INICIAL', S, P, V_CANTIDAD, V_COSTO, V_BODEGUERO,
                                             'INVENTARIO INICIAL 2026', TO_DATE('2026-01-02 08:00', 'YYYY-MM-DD HH24:MI'), USER);
        END LOOP;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Inventario inicial cargado.');
END;
/

DECLARE
    V_ID_COMPRA  NUMBER;
    V_PROVEEDOR  NUMBER;
    V_TIPO_PAGO  VARCHAR2(10);
    V_FECHA      DATE;
    V_COSTO      NUMBER(12,2);
    V_MINIMA     NUMBER;
    V_CANTIDAD   NUMBER;
    V_TC         NUMBER(10,4);
    V_PORCENTAJE NUMBER(5,2);
    V_SUBTOTAL   NUMBER(12,2);
    V_IMPUESTO   NUMBER(12,2);
    V_DIAS       NUMBER;
BEGIN
    FOR S IN 1..12 LOOP
        IF S <= 4 THEN
            V_PROVEEDOR := MOD(S, 3) + 1;
        ELSIF S <= 8 THEN
            V_PROVEEDOR := MOD(S, 2) + 4;
        ELSE
            V_PROVEEDOR := 6;
        END IF;

        IF MOD(S, 2) = 0 THEN
            V_TIPO_PAGO := 'CREDITO';
        ELSE
            V_TIPO_PAGO := 'CONTADO';
        END IF;

        SELECT P.TIPO_CAMBIO_QUETZAL, P.PORCENTAJE_IMPUESTO
          INTO V_TC, V_PORCENTAJE
          FROM SUCURSAL_9255 SU
         INNER JOIN REGION_9255 R ON R.ID_REGION = SU.ID_REGION
         INNER JOIN PAIS_9255 P   ON P.ID_PAIS = R.ID_PAIS
         WHERE SU.ID_SUCURSAL = S;

        V_FECHA := TO_DATE('2026-03-09 10:00', 'YYYY-MM-DD HH24:MI') + S;
        V_SUBTOTAL := 0;

        INSERT INTO COMPRA_9255 (ID_PROVEEDOR, ID_SUCURSAL, ID_EMPLEADO, NUMERO_DOCUMENTO, FECHA_EMISION, FECHA_RECEPCION,
                                 TIPO_PAGO, ESTADO, PORCENTAJE_IMPUESTO, TIPO_CAMBIO_QUETZAL)
        VALUES (V_PROVEEDOR, S, 3, 'FAC-' || (1000 + S), V_FECHA, V_FECHA + 2,
                V_TIPO_PAGO, 'RECIBIDA', V_PORCENTAJE, V_TC)
        RETURNING ID_COMPRA INTO V_ID_COMPRA;

        FOR P IN 1..42 LOOP
            IF MOD(P + S, 3) = 0 THEN
                SELECT PRECIO_COSTO, EXISTENCIA_MINIMA INTO V_COSTO, V_MINIMA FROM PRODUCTO_9255 WHERE ID_PRODUCTO = P;
                V_CANTIDAD := V_MINIMA * 2 + 10;

                INSERT INTO DETALLE_COMPRA_9255 (ID_COMPRA, ID_PRODUCTO, CANTIDAD, COSTO_UNITARIO, SUBTOTAL)
                VALUES (V_ID_COMPRA, P, V_CANTIDAD, ROUND(V_COSTO / V_TC, 2), ROUND(V_CANTIDAD * ROUND(V_COSTO / V_TC, 2), 2));
                V_SUBTOTAL := V_SUBTOTAL + ROUND(V_CANTIDAD * ROUND(V_COSTO / V_TC, 2), 2);

                PRC_REGISTRA_MOV_INVENTARIO_9255('INGRESO_COMPRA', S, P, V_CANTIDAD, V_COSTO, 4 + (S - 1) * 7 + 4,
                                                 'COMPRA ' || V_ID_COMPRA, V_FECHA + 2, USER);
            END IF;
        END LOOP;

        V_IMPUESTO := ROUND(V_SUBTOTAL * V_PORCENTAJE / 100, 2);
        UPDATE COMPRA_9255
           SET SUBTOTAL = V_SUBTOTAL, IMPUESTO = V_IMPUESTO, TOTAL = V_SUBTOTAL + V_IMPUESTO
         WHERE ID_COMPRA = V_ID_COMPRA;

        IF V_TIPO_PAGO = 'CREDITO' THEN
            SELECT DIAS_CREDITO INTO V_DIAS FROM PROVEEDOR_9255 WHERE ID_PROVEEDOR = V_PROVEEDOR;
            INSERT INTO CUENTA_POR_PAGAR_9255 (ID_COMPRA, MONTO_TOTAL, SALDO, FECHA_EMISION, FECHA_VENCIMIENTO)
            VALUES (V_ID_COMPRA, V_SUBTOTAL + V_IMPUESTO, V_SUBTOTAL + V_IMPUESTO, TRUNC(V_FECHA + 2), TRUNC(V_FECHA + 2) + V_DIAS);
        END IF;
    END LOOP;

    FOR C IN (SELECT ID_CUENTA_PAGAR, SALDO, FECHA_VENCIMIENTO FROM CUENTA_POR_PAGAR_9255) LOOP
        IF C.FECHA_VENCIMIENTO < DATE '2026-10-01' THEN
            INSERT INTO PAGO_PROVEEDOR_9255 (ID_CUENTA_PAGAR, ID_FORMA_PAGO, FECHA_PAGO, MONTO, NUMERO_REFERENCIA, BANCO)
            VALUES (C.ID_CUENTA_PAGAR, 3, C.FECHA_VENCIMIENTO, C.SALDO, 'TRF-' || C.ID_CUENTA_PAGAR, 'Banco Industrial');
            UPDATE CUENTA_POR_PAGAR_9255 SET SALDO = 0, ESTADO = 'PAGADA' WHERE ID_CUENTA_PAGAR = C.ID_CUENTA_PAGAR;
        END IF;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Compras registradas.');
END;
/

DECLARE
    V_DIA        DATE := DATE '2026-01-05';
    V_FECHA      DATE;
    V_SUCURSAL   NUMBER;
    V_PAIS       NUMBER;
    V_REGION     NUMBER;
    V_CLIENTE    NUMBER;
    V_VENDEDOR   NUMBER;
    V_TIPO_VENTA VARCHAR2(10);
    V_ENTREGA    VARCHAR2(10);
    V_DIRECCION  VARCHAR2(200);
    V_SERIE      VARCHAR2(10);
    V_NUMERO     NUMBER;
    V_PORCENTAJE NUMBER(5,2);
    V_MONEDA     CHAR(3);
    V_TC         NUMBER(10,4);
    V_ID_FACTURA NUMBER;
    V_LINEAS     NUMBER;
    V_PRODUCTO   NUMBER;
    V_MINIMA     NUMBER;
    V_CANTIDAD   NUMBER;
    V_EXISTENCIA NUMBER;
    V_TOTAL      NUMBER(12,2);
    V_LIMITE     NUMBER(12,2);
    V_DIAS       NUMBER;
    V_SALDO      NUMBER(12,2);
    V_FORMA      NUMBER;
    V_REFERENCIA VARCHAR2(40);
    V_FACTURAS   NUMBER := 0;
BEGIN
    WHILE V_DIA <= DATE '2026-10-19' LOOP
        IF TO_CHAR(V_DIA, 'DY', 'NLS_DATE_LANGUAGE=SPANISH') <> 'DOM' THEN
            FOR K IN 1..2 LOOP
                V_SUCURSAL := TRUNC(DBMS_RANDOM.VALUE(1, 13));
                V_PAIS     := CEIL(V_SUCURSAL / 4);
                V_VENDEDOR := 4 + (V_SUCURSAL - 1) * 7 + TRUNC(DBMS_RANDOM.VALUE(1, 3));

                IF DBMS_RANDOM.VALUE < 0.15 THEN
                    V_CLIENTE := 48 + V_PAIS;
                ELSE
                    IF DBMS_RANDOM.VALUE < 0.7 THEN
                        V_REGION := V_SUCURSAL;
                    ELSE
                        V_REGION := (V_PAIS - 1) * 4 + TRUNC(DBMS_RANDOM.VALUE(1, 5));
                    END IF;
                    V_CLIENTE := (V_REGION - 1) * 4 + TRUNC(DBMS_RANDOM.VALUE(1, 5));
                END IF;

                SELECT LIMITE_CREDITO, DIAS_CREDITO, DIRECCION INTO V_LIMITE, V_DIAS, V_DIRECCION
                  FROM CLIENTE_9255 WHERE ID_CLIENTE = V_CLIENTE;

                IF V_LIMITE > 0 AND DBMS_RANDOM.VALUE < 0.45 THEN
                    V_TIPO_VENTA := 'CREDITO';
                ELSE
                    V_TIPO_VENTA := 'CONTADO';
                END IF;

                IF DBMS_RANDOM.VALUE < 0.3 AND V_CLIENTE <= 48 THEN
                    V_ENTREGA := 'EMPRESA';
                ELSE
                    V_ENTREGA := 'CLIENTE';
                    V_DIRECCION := NULL;
                END IF;

                V_FECHA := V_DIA + TRUNC(DBMS_RANDOM.VALUE(8, 18)) / 24 + TRUNC(DBMS_RANDOM.VALUE(0, 60)) / 1440;

                SELECT SU.SERIE_FACTURA, P.PORCENTAJE_IMPUESTO, P.MONEDA_CODIGO, P.TIPO_CAMBIO_QUETZAL
                  INTO V_SERIE, V_PORCENTAJE, V_MONEDA, V_TC
                  FROM SUCURSAL_9255 SU
                 INNER JOIN REGION_9255 R ON R.ID_REGION = SU.ID_REGION
                 INNER JOIN PAIS_9255 P   ON P.ID_PAIS = R.ID_PAIS
                 WHERE SU.ID_SUCURSAL = V_SUCURSAL;

                UPDATE SUCURSAL_9255 SET CORRELATIVO_FACTURA = CORRELATIVO_FACTURA + 1 WHERE ID_SUCURSAL = V_SUCURSAL;
                SELECT CORRELATIVO_FACTURA INTO V_NUMERO FROM SUCURSAL_9255 WHERE ID_SUCURSAL = V_SUCURSAL;

                INSERT INTO FACTURA_9255 (ID_SUCURSAL, ID_CLIENTE, ID_EMPLEADO, SERIE, NUMERO, FECHA_EMISION, TIPO_VENTA,
                                          TIPO_ENTREGA, DIRECCION_ENTREGA, PORCENTAJE_IMPUESTO, MONEDA_CODIGO, TIPO_CAMBIO_QUETZAL)
                VALUES (V_SUCURSAL, V_CLIENTE, V_VENDEDOR, V_SERIE, V_NUMERO, V_FECHA, V_TIPO_VENTA,
                        V_ENTREGA, V_DIRECCION, V_PORCENTAJE, V_MONEDA, V_TC)
                RETURNING ID_FACTURA INTO V_ID_FACTURA;

                V_LINEAS := TRUNC(DBMS_RANDOM.VALUE(1, 5));
                FOR L IN 1..V_LINEAS LOOP
                    V_PRODUCTO := TRUNC(42 * POWER(DBMS_RANDOM.VALUE, 1.7)) + 1;
                    SELECT EXISTENCIA_MINIMA INTO V_MINIMA FROM PRODUCTO_9255 WHERE ID_PRODUCTO = V_PRODUCTO;
                    IF V_MINIMA >= 100 THEN
                        V_CANTIDAD := 10 * TRUNC(DBMS_RANDOM.VALUE(1, 9));
                    ELSIF V_MINIMA >= 30 THEN
                        V_CANTIDAD := TRUNC(DBMS_RANDOM.VALUE(2, 13));
                    ELSE
                        V_CANTIDAD := TRUNC(DBMS_RANDOM.VALUE(1, 4));
                    END IF;

                    SELECT NVL(MAX(EXISTENCIA), 0) INTO V_EXISTENCIA
                      FROM INVENTARIO_9255 WHERE ID_SUCURSAL = V_SUCURSAL AND ID_PRODUCTO = V_PRODUCTO;
                    IF V_EXISTENCIA >= V_CANTIDAD THEN
                        INSERT INTO DETALLE_FACTURA_9255 (ID_FACTURA, ID_PRODUCTO, CANTIDAD)
                        VALUES (V_ID_FACTURA, V_PRODUCTO, V_CANTIDAD);
                    END IF;
                END LOOP;

                SELECT COUNT(*) INTO V_LINEAS FROM DETALLE_FACTURA_9255 WHERE ID_FACTURA = V_ID_FACTURA;
                IF V_LINEAS = 0 THEN
                    FOR P IN 1..42 LOOP
                        SELECT NVL(MAX(EXISTENCIA), 0) INTO V_EXISTENCIA
                          FROM INVENTARIO_9255 WHERE ID_SUCURSAL = V_SUCURSAL AND ID_PRODUCTO = P;
                        IF V_LINEAS = 0 AND V_EXISTENCIA >= 1 THEN
                            INSERT INTO DETALLE_FACTURA_9255 (ID_FACTURA, ID_PRODUCTO, CANTIDAD)
                            VALUES (V_ID_FACTURA, P, 1);
                            V_LINEAS := 1;
                        END IF;
                    END LOOP;
                END IF;

                SELECT TOTAL INTO V_TOTAL FROM FACTURA_9255 WHERE ID_FACTURA = V_ID_FACTURA;

                IF V_TIPO_VENTA = 'CREDITO' THEN
                    SELECT NVL(SUM(SALDO), 0) INTO V_SALDO
                      FROM CUENTA_POR_COBRAR_9255 WHERE ID_CLIENTE = V_CLIENTE AND ESTADO = 'PENDIENTE';
                    IF V_SALDO + V_TOTAL > V_LIMITE THEN
                        V_TIPO_VENTA := 'CONTADO';
                        UPDATE FACTURA_9255 SET TIPO_VENTA = 'CONTADO' WHERE ID_FACTURA = V_ID_FACTURA;
                    END IF;
                END IF;

                IF V_TIPO_VENTA = 'CONTADO' THEN
                    IF DBMS_RANDOM.VALUE < 0.55 THEN
                        V_FORMA := 1;
                        V_REFERENCIA := NULL;
                    ELSE
                        V_FORMA := TRUNC(DBMS_RANDOM.VALUE(2, 5));
                        V_REFERENCIA := TO_CHAR(TRUNC(DBMS_RANDOM.VALUE(10000000, 99999999)));
                    END IF;
                    INSERT INTO PAGO_FACTURA_9255 (ID_FACTURA, ID_FORMA_PAGO, FECHA_PAGO, MONTO, NUMERO_REFERENCIA)
                    VALUES (V_ID_FACTURA, V_FORMA, V_FECHA, V_TOTAL, V_REFERENCIA);
                ELSE
                    INSERT INTO CUENTA_POR_COBRAR_9255 (ID_FACTURA, ID_CLIENTE, MONTO_TOTAL, SALDO, FECHA_EMISION, FECHA_VENCIMIENTO)
                    VALUES (V_ID_FACTURA, V_CLIENTE, V_TOTAL, V_TOTAL, TRUNC(V_FECHA), TRUNC(V_FECHA) + V_DIAS);
                END IF;

                UPDATE FACTURA_9255 SET ESTADO = 'EMITIDA' WHERE ID_FACTURA = V_ID_FACTURA;
                V_FACTURAS := V_FACTURAS + 1;
            END LOOP;
        END IF;
        V_DIA := V_DIA + 1;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Facturas emitidas: ' || V_FACTURAS);
END;
/

DECLARE
    V_FECHA DATE;
    V_AZAR  NUMBER;
BEGIN
    FOR C IN (SELECT ID_CUENTA_COBRAR, SALDO, FECHA_EMISION FROM CUENTA_POR_COBRAR_9255 ORDER BY ID_CUENTA_COBRAR) LOOP
        V_FECHA := C.FECHA_EMISION + TRUNC(DBMS_RANDOM.VALUE(3, 26)) + 10 / 24;
        V_AZAR  := DBMS_RANDOM.VALUE;
        IF V_FECHA < DATE '2026-10-20' THEN
            IF V_AZAR < 0.5 THEN
                INSERT INTO ABONO_CLIENTE_9255 (ID_CUENTA_COBRAR, ID_FORMA_PAGO, FECHA_ABONO, MONTO, NUMERO_REFERENCIA, BANCO)
                VALUES (C.ID_CUENTA_COBRAR, 3, V_FECHA, C.SALDO, 'TRF-' || C.ID_CUENTA_COBRAR, 'Banco Industrial');
                UPDATE CUENTA_POR_COBRAR_9255 SET SALDO = 0, ESTADO = 'PAGADA' WHERE ID_CUENTA_COBRAR = C.ID_CUENTA_COBRAR;
            ELSIF V_AZAR < 0.75 THEN
                INSERT INTO ABONO_CLIENTE_9255 (ID_CUENTA_COBRAR, ID_FORMA_PAGO, FECHA_ABONO, MONTO)
                VALUES (C.ID_CUENTA_COBRAR, 1, V_FECHA, ROUND(C.SALDO / 2, 2));
                UPDATE CUENTA_POR_COBRAR_9255 SET SALDO = SALDO - ROUND(C.SALDO / 2, 2) WHERE ID_CUENTA_COBRAR = C.ID_CUENTA_COBRAR;
            END IF;
        END IF;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Abonos registrados.');
END;
/

DECLARE
    V_ID_ENVIO NUMBER;
BEGIN
    FOR F IN (SELECT ID_FACTURA, ID_SUCURSAL, FECHA_EMISION, DIRECCION_ENTREGA
                FROM FACTURA_9255
               WHERE TIPO_ENTREGA = 'EMPRESA'
               ORDER BY FECHA_EMISION) LOOP
        IF F.FECHA_EMISION < DATE '2026-10-17' THEN
            INSERT INTO ENVIO_9255 (ID_FACTURA, ID_SUCURSAL, ID_VEHICULO, ID_PILOTO, ID_EMPLEADO_RESPONSABLE, FECHA_PROGRAMADA,
                                    FECHA_SALIDA, FECHA_ENTREGA, DIRECCION_ENTREGA, ESTADO)
            VALUES (F.ID_FACTURA, F.ID_SUCURSAL, F.ID_SUCURSAL, F.ID_SUCURSAL,
                    CASE WHEN MOD(F.ID_FACTURA, 4) = 0 THEN 4 + (F.ID_SUCURSAL - 1) * 7 ELSE 4 + (F.ID_SUCURSAL - 1) * 7 + 5 END,
                    TRUNC(F.FECHA_EMISION) + 1, TRUNC(F.FECHA_EMISION) + 1 + 8 / 24, TRUNC(F.FECHA_EMISION) + 1 + 13 / 24,
                    F.DIRECCION_ENTREGA, 'ENTREGADO')
            RETURNING ID_ENVIO INTO V_ID_ENVIO;
        ELSE
            INSERT INTO ENVIO_9255 (ID_FACTURA, ID_SUCURSAL, ID_VEHICULO, ID_PILOTO, ID_EMPLEADO_RESPONSABLE, FECHA_PROGRAMADA,
                                    DIRECCION_ENTREGA, ESTADO)
            VALUES (F.ID_FACTURA, F.ID_SUCURSAL, F.ID_SUCURSAL, F.ID_SUCURSAL, 4 + (F.ID_SUCURSAL - 1) * 7 + 5,
                    TRUNC(F.FECHA_EMISION) + 1, F.DIRECCION_ENTREGA, 'PROGRAMADO')
            RETURNING ID_ENVIO INTO V_ID_ENVIO;
        END IF;

        INSERT INTO DETALLE_ENVIO_9255 (ID_ENVIO, ID_DETALLE_FACTURA, CANTIDAD)
        SELECT V_ID_ENVIO, ID_DETALLE_FACTURA, CANTIDAD
          FROM DETALLE_FACTURA_9255
         WHERE ID_FACTURA = F.ID_FACTURA;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Envios registrados.');
END;
/

DECLARE
    V_SERIE  VARCHAR2(10);
    V_NUMERO NUMBER;
    V_MONTO  NUMBER(12,2);
BEGIN
    FOR F IN (SELECT ID_FACTURA, ID_SUCURSAL, ID_EMPLEADO, TOTAL, FECHA_EMISION
                FROM FACTURA_9255
               WHERE MOD(ID_FACTURA, 61) = 7 AND FECHA_EMISION < DATE '2026-10-15') LOOP
        UPDATE SUCURSAL_9255 SET CORRELATIVO_NOTA_CREDITO = CORRELATIVO_NOTA_CREDITO + 1 WHERE ID_SUCURSAL = F.ID_SUCURSAL;
        SELECT 'NC' || SERIE_FACTURA, CORRELATIVO_NOTA_CREDITO INTO V_SERIE, V_NUMERO
          FROM SUCURSAL_9255 WHERE ID_SUCURSAL = F.ID_SUCURSAL;
        V_MONTO := ROUND(F.TOTAL * 0.05, 2);

        INSERT INTO NOTA_CREDITO_9255 (ID_FACTURA, ID_EMPLEADO, ID_EMPLEADO_AUTORIZA, SERIE, NUMERO, FECHA_EMISION,
                                       TIPO, MOTIVO, MONTO, ESTADO)
        VALUES (F.ID_FACTURA, F.ID_EMPLEADO, 4 + (F.ID_SUCURSAL - 1) * 7, V_SERIE, V_NUMERO, F.FECHA_EMISION + 2,
                'DESCUENTO', 'Descuento por volumen autorizado despues de la venta', V_MONTO, 'EMITIDA');

        UPDATE CUENTA_POR_COBRAR_9255
           SET SALDO = GREATEST(SALDO - V_MONTO, 0),
               ESTADO = CASE WHEN SALDO - V_MONTO <= 0 THEN 'PAGADA' ELSE 'PENDIENTE' END
         WHERE ID_FACTURA = F.ID_FACTURA;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Notas de credito por descuento registradas.');
END;
/

DECLARE
    V_SERIE    VARCHAR2(10);
    V_NUMERO   NUMBER;
    V_MONTO    NUMBER(12,2);
    V_ESTADO   VARCHAR2(10);
    V_ID_NOTA  NUMBER;
    V_PRODUCTO NUMBER;
    V_COSTO    NUMBER(12,2);
BEGIN
    FOR F IN (SELECT F.ID_FACTURA, F.ID_SUCURSAL, F.ID_EMPLEADO, F.FECHA_EMISION, F.PORCENTAJE_IMPUESTO,
                     MIN(D.ID_DETALLE_FACTURA) AS ID_DETALLE
                FROM FACTURA_9255 F
               INNER JOIN DETALLE_FACTURA_9255 D ON D.ID_FACTURA = F.ID_FACTURA
               WHERE MOD(F.ID_FACTURA, 53) = 11 AND F.FECHA_EMISION < DATE '2026-10-15'
               GROUP BY F.ID_FACTURA, F.ID_SUCURSAL, F.ID_EMPLEADO, F.FECHA_EMISION, F.PORCENTAJE_IMPUESTO) LOOP
        IF MOD(F.ID_FACTURA, 3) = 1 THEN
            V_ESTADO := 'DANADO';
        ELSE
            V_ESTADO := 'BUENO';
        END IF;

        SELECT D.ID_PRODUCTO, P.PRECIO_COSTO, ROUND(D.SUBTOTAL / D.CANTIDAD * (1 + F.PORCENTAJE_IMPUESTO / 100), 2)
          INTO V_PRODUCTO, V_COSTO, V_MONTO
          FROM DETALLE_FACTURA_9255 D
         INNER JOIN PRODUCTO_9255 P ON P.ID_PRODUCTO = D.ID_PRODUCTO
         WHERE D.ID_DETALLE_FACTURA = F.ID_DETALLE;

        UPDATE SUCURSAL_9255 SET CORRELATIVO_NOTA_CREDITO = CORRELATIVO_NOTA_CREDITO + 1 WHERE ID_SUCURSAL = F.ID_SUCURSAL;
        SELECT 'NC' || SERIE_FACTURA, CORRELATIVO_NOTA_CREDITO INTO V_SERIE, V_NUMERO
          FROM SUCURSAL_9255 WHERE ID_SUCURSAL = F.ID_SUCURSAL;

        INSERT INTO NOTA_CREDITO_9255 (ID_FACTURA, ID_EMPLEADO, ID_EMPLEADO_AUTORIZA, SERIE, NUMERO, FECHA_EMISION,
                                       TIPO, MOTIVO, MONTO, ESTADO)
        VALUES (F.ID_FACTURA, F.ID_EMPLEADO, 4 + (F.ID_SUCURSAL - 1) * 7, V_SERIE, V_NUMERO, F.FECHA_EMISION + 3, 'DEVOLUCION',
                CASE V_ESTADO WHEN 'DANADO' THEN 'Producto con defecto de fabrica' ELSE 'El cliente compro una medida equivocada' END,
                V_MONTO, 'EMITIDA')
        RETURNING ID_NOTA_CREDITO INTO V_ID_NOTA;

        INSERT INTO DETALLE_NOTA_CREDITO_9255 (ID_NOTA_CREDITO, ID_DETALLE_FACTURA, CANTIDAD, ESTADO_PRODUCTO, MONTO)
        VALUES (V_ID_NOTA, F.ID_DETALLE, 1, V_ESTADO, V_MONTO);

        IF V_ESTADO = 'BUENO' THEN
            PRC_REGISTRA_MOV_INVENTARIO_9255('INGRESO_DEVOLUCION', F.ID_SUCURSAL, V_PRODUCTO, 1, V_COSTO, F.ID_EMPLEADO,
                                             'NOTA DE CREDITO ' || V_SERIE || '-' || V_NUMERO, F.FECHA_EMISION + 3, USER);
        END IF;

        UPDATE CUENTA_POR_COBRAR_9255
           SET SALDO = GREATEST(SALDO - V_MONTO, 0),
               ESTADO = CASE WHEN SALDO - V_MONTO <= 0 THEN 'PAGADA' ELSE 'PENDIENTE' END
         WHERE ID_FACTURA = F.ID_FACTURA;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Devoluciones registradas.');
END;
/

BEGIN
    FOR D IN (SELECT D.ID_DETALLE_FACTURA, F.ID_EMPLEADO, F.FECHA_EMISION
                FROM DETALLE_FACTURA_9255 D
               INNER JOIN FACTURA_9255 F ON F.ID_FACTURA = D.ID_FACTURA
               WHERE D.FECHA_FIN_GARANTIA IS NOT NULL
                 AND MOD(D.ID_DETALLE_FACTURA, 47) = 5
                 AND F.FECHA_EMISION < DATE '2026-09-15') LOOP
        IF MOD(D.ID_DETALLE_FACTURA, 2) = 0 THEN
            INSERT INTO RECLAMO_GARANTIA_9255 (ID_DETALLE_FACTURA, ID_EMPLEADO, FECHA_RECLAMO, DESCRIPCION_FALLA,
                                               ESTADO, FECHA_RESOLUCION, RESOLUCION)
            VALUES (D.ID_DETALLE_FACTURA, D.ID_EMPLEADO, D.FECHA_EMISION + 30, 'El producto dejo de funcionar con poco uso',
                    'REPARADO', D.FECHA_EMISION + 40, 'Revisado y reparado por el taller del proveedor');
        ELSE
            INSERT INTO RECLAMO_GARANTIA_9255 (ID_DETALLE_FACTURA, ID_EMPLEADO, FECHA_RECLAMO, DESCRIPCION_FALLA)
            VALUES (D.ID_DETALLE_FACTURA, D.ID_EMPLEADO, D.FECHA_EMISION + 30, 'El producto dejo de funcionar con poco uso');
        END IF;
    END LOOP;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Reclamos de garantia registrados.');
END;
/

